    check(selectors.size()==12,"not all twelve selector paths exercised");
    // No must preserve the exact slots and combination chooser.
    {auto inv=inventory(21);inv.slots()[3]=Inventory::pack(22,1);StatusMenu menu;menu.active=menu.combining=true;menu.combine_from=2;menu.selected=3;menu.message_source=[&](unsigned index){return ui?ui->system_message(index):Message{0xff04,0xff04,0xffff};};const auto before=inv.items;menu.input(MenuInput::Confirm,inv);check(menu.message.index()==155,"herb question missing");while(!menu.message.choices())menu.input(MenuInput::Confirm,inv);menu.input(MenuInput::Right,inv);menu.input(MenuInput::Confirm,inv);check(inv.items==before&&menu.combining,"herb No mutates inventory");}
    audit<<"\n## Files\n\nAll 24 page-count, message-offset and wallpaper entries are read from original `fileview.c`. The acquired-file bitset remains in original inventory word 383. Native navigation/text viewing is implemented; original book/tag animation and contextual manual-page filtering are pending.\n\n";
